local function lastIndexOf(p1, p2, p3) -- line: 2
    local v1 = string.len(p1)

    if p3 then
        local v2 = p3

        if p3 < 1 then
            v2 = 1
        end

        if not (v1 < p3) then
            v1 = v2
        end
    end

    if p2 == "" then
        return v1
    end

    local n1 = 0
    local v3

    while true do
        local v4

        v4, n1 = string.find(p1, p2, n1 + 1, true)

        if v4 == nil or v1 < v4 then
            break
        end

        v3 = v4
    end

    if v3 == nil then
        return -1
    end

    return v3
end

return lastIndexOf
